/**
 * Brand assets for Ayesha Herbal & Beauty.
 *
 * The roundel is recreated in client/public/brand/ayesha-logo.svg from the
 * brand's own packaging (pink disc, crescent, serif wordmark). Derived assets
 * are generated by scripts/brand-assets.mjs.
 *
 * All URLs honour Vite's BASE_URL so they resolve both locally and under a
 * hosted sub-path.
 */
const BASE = import.meta.env.BASE_URL;

/** Full brand roundel. */
export const LOGO_ORIGINAL = `${BASE}brand/ayesha-logo.png`;

/** Roundel on transparency — for light surfaces (navbar, footer, admin). */
export const LOGO_TRANSPARENT = `${BASE}brand/ayesha-logo-transparent.png`;

/** Empty padding trimmed — best for small UI slots. */
export const LOGO_TRIMMED = `${BASE}brand/ayesha-logo-trimmed.png`;

/** Vector roundel (crisp at every size). */
export const LOGO_SVG = `${BASE}brand/ayesha-logo.svg`;

/**
 * Collection hero visual — client-supplied product photography, so it ships
 * from client/public rather than the uploads folder.
 */
export const HERO_IMAGE = `${BASE}images/hero-products.webp`;

/**
 * About-page visual. The brand does not currently supply a founder portrait,
 * so the collection image is used (and the admin can override it later).
 */
export const ABOUT_IMAGE = HERO_IMAGE;

/** Social sharing image (1200×630). */
export const OG_IMAGE = `${BASE}og-image.png`;

/** Absolute URL of the social image, as crawlers require. */
export const SITE_URL = import.meta.env.VITE_PUBLIC_SITE_URL ?? 'http://localhost:5173';
export const OG_IMAGE_ABSOLUTE = new URL(OG_IMAGE, SITE_URL).href;
